using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;

// Builds the Halloween background (jack-o'-lanterns, moon and sky, silhouettes, bats, cobwebs, porch frame)
// from the FBX files generated by Tools/Blender/build_environment.py. Build() lays everything out under one
// "Environment" root for PrototypeSceneBuilder; the menu items rebuild the assets and a preview scene.
// Safe to re-run; it overwrites its own outputs.
public static class EnvironmentBuilder
{
    const string ModelDir = "Assets/Models/Environment";
    const string MaterialDir = "Assets/Materials/Environment";
    const string PrefabDir = "Assets/Prefabs/Environment";
    const string ScenePath = "Assets/Scenes/EnvironmentPreview.unity";

    static readonly string[] Models =
        { "Env_Pumpkin", "Env_Bat", "Env_Cobweb", "Env_Porch", "Env_Silhouettes", "Env_Sky" };
    static readonly string[] PrefabNames = { "JackOLantern", "Bat", "Cobweb", "Porch", "Silhouettes", "Sky" };

    // The game camera (see PrototypeSceneBuilder.BuildCameraAndHand); the layout is built around it.
    static readonly Vector3 CameraPosition = new Vector3(0f, 1.6f, 0f);

    // Jack-o'-lanterns beside the queue, never inside x [-7, 2.5], z [1.5, 11.5]: (x, z, scale).
    static readonly Vector3[] Pumpkins =
    {
        new Vector3(3.3f, 3.8f, 0.9f), new Vector3(4.4f, 6.8f, 1.15f), new Vector3(3.7f, 10f, 1f),
        new Vector3(-7.6f, 8.5f, 1.1f), new Vector3(-8.4f, 11f, 1.3f),
    };

    // Bats circle in front of the moon and over the back of the yard: (center, radius, degrees per second).
    static readonly (Vector3 center, float radius, float speed)[] Bats =
    {
        (new Vector3(7f, 6.5f, 19f), 3.2f, 34f), (new Vector3(10f, 7.8f, 23f), 4f, -28f),
        (new Vector3(4.5f, 5.6f, 16f), 2.5f, 42f), (new Vector3(-5f, 6.2f, 15f), 3f, -36f),
        (new Vector3(-1f, 8f, 22f), 4.5f, 26f),
    };

    // Webs hung in tree forks and on the fence: (position, size, mirrored).
    static readonly (Vector3 position, float size, bool mirror)[] Webs =
    {
        (new Vector3(-8f, 4.4f, 18f), 2.4f, false), (new Vector3(4.2f, 4f, 16.5f), 2f, true),
        (new Vector3(9.3f, 4.6f, 15.5f), 2.2f, false), (new Vector3(-13.2f, 1.25f, 13.3f), 1.1f, true),
    };

    [MenuItem("Tools/Environment/Rebuild Prefabs")]
    public static void RebuildAssets()
    {
        AssetDatabase.Refresh(); // pick up freshly exported FBX files
        foreach (var model in Models)
        {
            if (AssetDatabase.LoadAssetAtPath<GameObject>($"{ModelDir}/{model}.fbx") == null)
            {
                Debug.LogError($"[Environment] {ModelDir}/{model}.fbx is missing. Run: blender -b --factory-startup " +
                    "--python Tools/Blender/build_environment.py -- --out Assets/Models/Environment");
                return;
            }
        }
        EnsureFolder(MaterialDir);
        EnsureFolder(PrefabDir);
        CreateMaterials();
        ConfigureImporters();
        CreatePrefabs();
        AssetDatabase.SaveAssets();
        Debug.Log("[Environment] Rebuilt materials and prefabs.");
    }

    // Instantiates the whole background under one root named "Environment" and returns it.
    // The caller owns the scene (this does not save anything).
    public static GameObject Build()
    {
        if (PrefabNames.Any(n => AssetDatabase.LoadAssetAtPath<GameObject>($"{PrefabDir}/{n}.prefab") == null))
            RebuildAssets();

        var root = new GameObject("Environment");
        Spawn("Sky", root.transform);
        Spawn("Silhouettes", root.transform);
        var porch = Spawn("Porch", root.transform);

        var lanterns = new GameObject("JackOLanterns").transform;
        lanterns.SetParent(root.transform, false);
        for (var i = 0; i < Pumpkins.Length; i++)
        {
            var spot = Pumpkins[i];
            var pumpkin = Spawn("JackOLantern", lanterns);
            pumpkin.transform.localPosition = new Vector3(spot.x, 0f, spot.y);
            pumpkin.transform.localRotation = FaceCamera(pumpkin.transform.localPosition, (i % 2 == 0 ? 8f : -8f));
            pumpkin.transform.localScale = Vector3.one * spot.z;
        }

        var bats = new GameObject("Bats").transform;
        bats.SetParent(root.transform, false);
        for (var i = 0; i < Bats.Length; i++)
        {
            var bat = Spawn("Bat", bats);
            bat.GetComponent<BatFlight>().Configure(Bats[i].center, Bats[i].radius, Bats[i].speed, i * 71f);
            PrefabUtility.RecordPrefabInstancePropertyModifications(bat.GetComponent<BatFlight>());
        }

        var webs = new GameObject("Cobwebs").transform;
        webs.SetParent(root.transform, false);
        foreach (var (position, size, mirror) in Webs)
        {
            var web = Spawn("Cobweb", webs);
            web.transform.localPosition = position;
            web.transform.localRotation = FaceCamera(position, 0f);
            web.transform.localScale = new Vector3(mirror ? -size : size, -size, 1f);
        }

        porch.GetComponent<PorchFrame>().FitToCamera();
        return root;
    }

    [MenuItem("Tools/Environment/Rebuild Preview Scene")]
    public static void BuildPreviewScene()
    {
        RebuildAssets();
        var scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);

        // Same look as PrototypeSceneBuilder.BuildWorld / BuildCameraAndHand.
        var light = UnityEngine.Object.FindFirstObjectByType<Light>();
        light.color = new Color(1f, 0.72f, 0.45f);
        light.intensity = 1.3f;
        light.transform.rotation = Quaternion.Euler(50f, -30f, 0f);
        RenderSettings.skybox = null;
        RenderSettings.ambientMode = AmbientMode.Flat;
        RenderSettings.ambientLight = new Color(0.25f, 0.18f, 0.32f);
        RenderSettings.fog = true;
        RenderSettings.fogMode = FogMode.Linear;
        RenderSettings.fogColor = new Color(0.12f, 0.06f, 0.18f);
        RenderSettings.fogStartDistance = 6f;
        RenderSettings.fogEndDistance = 22f;

        var cam = Camera.main;
        cam.clearFlags = CameraClearFlags.SolidColor;
        cam.backgroundColor = new Color(0.12f, 0.06f, 0.18f);
        cam.nearClipPlane = 0.05f;
        cam.farClipPlane = 60f;
        cam.fieldOfView = 60f;
        cam.transform.SetPositionAndRotation(CameraPosition, Quaternion.Euler(8f, 0f, 0f));

        var ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
        ground.name = "Ground";
        ground.transform.position = new Vector3(0f, 0f, 12f);
        ground.transform.localScale = new Vector3(3f, 1f, 6f);
        var groundMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/Ground.mat");
        if (groundMat != null)
            ground.GetComponent<Renderer>().sharedMaterial = groundMat;

        // Stand-ins for the queue (slots as in PrototypeSceneBuilder.BuildQueue) to judge the clear zone.
        var markers = new GameObject("QueueMarkers (preview only)").transform;
        for (var i = 0; i < 8; i++)
        {
            var marker = GameObject.CreatePrimitive(PrimitiveType.Capsule);
            marker.name = "Slot" + i;
            marker.transform.SetParent(markers, false);
            marker.transform.position = new Vector3(-i * 0.7f, 0.45f, 2.6f + i * 1.1f);
            marker.transform.localScale = new Vector3(0.6f, 0.45f, 0.6f);
            UnityEngine.Object.DestroyImmediate(marker.GetComponent<Collider>());
        }

        Build();
        EditorSceneManager.SaveScene(scene, ScenePath);
        Debug.Log($"[Environment] Preview scene saved to {ScenePath}. Look through the Main Camera in the Game view.");
    }

    // ---------------------------------------------------------------- materials

    static void CreateMaterials()
    {
        var prop = Shader.Find("Fangame/EnvironmentProp");
        // name, color, intensity, light, fog, flicker, flicker speed, flap, flap speed, double sided
        Prop(prop, "EnvPumpkin", new Color(0.62f, 0.24f, 0.04f), 1f, 1f, 0.7f, 0f, 0f, 0f, 0f, false);
        Prop(prop, "EnvStem", new Color(0.12f, 0.16f, 0.05f), 1f, 1f, 0.7f, 0f, 0f, 0f, 0f, false);
        Prop(prop, "EnvGlow", new Color(1f, 0.58f, 0.12f), 1.1f, 0f, 0.25f, 0.28f, 9f, 0f, 0f, false);
        Prop(prop, "EnvWindow", new Color(0.95f, 0.62f, 0.2f), 1f, 0f, 0f, 0.15f, 3f, 0f, 0f, true);
        Prop(prop, "EnvBat", new Color(0.02f, 0.012f, 0.03f), 1f, 0f, 0f, 0f, 0f, 0.5f, 11f, true);
        Prop(prop, "EnvPorch", new Color(0.05f, 0.03f, 0.04f), 1f, 0.3f, 0f, 0f, 0f, 0f, 0f, true);
        Prop(prop, "EnvSilNear", new Color(0.025f, 0.015f, 0.04f), 1f, 0f, 0.35f, 0f, 0f, 0f, 0f, true);
        Prop(prop, "EnvSilMid", new Color(0.045f, 0.025f, 0.075f), 1f, 0f, 0f, 0f, 0f, 0f, 0f, true);
        Prop(prop, "EnvSilFar", new Color(0.075f, 0.04f, 0.12f), 1f, 0f, 0f, 0f, 0f, 0f, 0f, true);
        Plain("EnvHalo", "Fangame/EnvironmentHalo");
        Plain("EnvCobweb", "Fangame/EnvironmentCobweb");
        Plain("EnvSky", "Fangame/EnvironmentSky");
        Plain("EnvMoon", "Fangame/EnvironmentMoon");
    }

    static Material GetMaterial(string name, Shader shader)
    {
        var path = $"{MaterialDir}/{name}.mat";
        var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
        if (mat == null)
        {
            mat = new Material(shader);
            AssetDatabase.CreateAsset(mat, path);
        }
        // Reset to the shader's defaults so removed or renamed properties never linger.
        var fresh = new Material(shader);
        mat.shader = shader;
        mat.CopyPropertiesFromMaterial(fresh);
        UnityEngine.Object.DestroyImmediate(fresh);
        EditorUtility.SetDirty(mat);
        return mat;
    }

    static void Plain(string name, string shaderName)
    {
        GetMaterial(name, Shader.Find(shaderName));
    }

    static void Prop(Shader shader, string name, Color color, float intensity, float light, float fog,
        float flicker, float flickerSpeed, float flap, float flapSpeed, bool doubleSided)
    {
        var mat = GetMaterial(name, shader);
        mat.SetColor("_BaseColor", color);
        mat.SetFloat("_Intensity", intensity);
        mat.SetFloat("_LightAmount", light);
        mat.SetFloat("_FogAmount", fog);
        mat.SetFloat("_FlickerAmount", flicker);
        if (flickerSpeed > 0f)
            mat.SetFloat("_FlickerSpeed", flickerSpeed);
        mat.SetFloat("_FlapAmount", flap);
        if (flapSpeed > 0f)
            mat.SetFloat("_FlapSpeed", flapSpeed);
        mat.SetFloat("_Cull", doubleSided ? 0f : 2f);
    }

    static readonly string[] MaterialNames =
    {
        "EnvPumpkin", "EnvStem", "EnvGlow", "EnvWindow", "EnvBat", "EnvPorch", "EnvSilNear", "EnvSilMid", "EnvSilFar",
        "EnvHalo", "EnvCobweb", "EnvSky", "EnvMoon",
    };

    static void ConfigureImporters()
    {
        foreach (var model in Models)
        {
            var importer = (ModelImporter)AssetImporter.GetAtPath($"{ModelDir}/{model}.fbx");
            importer.animationType = ModelImporterAnimationType.None;
            importer.importAnimation = false;
            importer.importCameras = false;
            importer.importLights = false;
            importer.importBlendShapes = false;
            importer.importNormals = ModelImporterNormals.Import;
            importer.importTangents = ModelImporterTangents.None;
            importer.meshCompression = ModelImporterMeshCompression.Off;

            // FBX slot names match the project material names.
            foreach (var remap in importer.GetExternalObjectMap().Keys.ToList())
                importer.RemoveRemap(remap);
            foreach (var name in MaterialNames)
                importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), name),
                    AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{name}.mat"));
            importer.SaveAndReimport();
        }
    }

    // ---------------------------------------------------------------- prefabs

    static void CreatePrefabs()
    {
        SavePrefab(Instance("Env_Pumpkin"), "JackOLantern");

        var bat = Instance("Env_Bat");
        bat.AddComponent<BatFlight>();
        SavePrefab(bat, "Bat");

        var web = SavePrefab(Instance("Env_Cobweb"), "Cobweb");

        var porch = Instance("Env_Porch");
        var frame = porch.AddComponent<PorchFrame>();
        var webLeft = (GameObject)PrefabUtility.InstantiatePrefab(web, porch.transform);
        webLeft.name = "WebL";
        var webRight = (GameObject)PrefabUtility.InstantiatePrefab(web, porch.transform);
        webRight.name = "WebR";
        var so = new SerializedObject(frame);
        foreach (var (field, child) in new[]
            { ("postLeft", "PostL"), ("postRight", "PostR"), ("header", "Header"), ("fascia", "Fascia"),
              ("bracketLeft", "BracketL"), ("bracketRight", "BracketR"), ("webLeft", "WebL"), ("webRight", "WebR") })
            so.FindProperty(field).objectReferenceValue = porch.transform.Find(child);
        so.ApplyModifiedPropertiesWithoutUndo();
        SavePrefab(porch, "Porch");

        SavePrefab(Instance("Env_Silhouettes"), "Silhouettes");
        SavePrefab(Instance("Env_Sky"), "Sky");
    }

    static GameObject Instance(string model)
    {
        var go = (GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>($"{ModelDir}/{model}.fbx"));
        foreach (var r in go.GetComponentsInChildren<Renderer>(true))
        {
            r.shadowCastingMode = ShadowCastingMode.Off;
            r.receiveShadows = false;
            r.lightProbeUsage = LightProbeUsage.Off;
            r.reflectionProbeUsage = ReflectionProbeUsage.Off;
        }
        return go;
    }

    static GameObject SavePrefab(GameObject go, string name)
    {
        go.name = name;
        var prefab = PrefabUtility.SaveAsPrefabAsset(go, $"{PrefabDir}/{name}.prefab");
        UnityEngine.Object.DestroyImmediate(go);
        return prefab;
    }

    static GameObject Spawn(string prefabName, Transform parent)
    {
        var prefab = AssetDatabase.LoadAssetAtPath<GameObject>($"{PrefabDir}/{prefabName}.prefab");
        return (GameObject)PrefabUtility.InstantiatePrefab(prefab, parent);
    }

    // Model front is +Z, so this turns a prop at `position` toward the camera (with a little yaw jitter).
    static Quaternion FaceCamera(Vector3 position, float yawJitter)
    {
        var toCamera = CameraPosition - position;
        toCamera.y = 0f;
        return Quaternion.LookRotation(toCamera) * Quaternion.Euler(0f, yawJitter, 0f);
    }

    static void EnsureFolder(string path)
    {
        if (AssetDatabase.IsValidFolder(path))
            return;
        var parent = Path.GetDirectoryName(path).Replace('\\', '/');
        EnsureFolder(parent);
        AssetDatabase.CreateFolder(parent, Path.GetFileName(path));
    }
}
